def is_colorful(m):
    if m < 100:
        return False
    n = 99
    L = 100
    k = (m + L - 1) // L
    return m >= n * k

# Test some values around 9700
for m in range(9600, 9800):
    if not is_colorful(m):
        print(f"m={m} is not colorful")
    else:
        pass

# Let's find the largest m < 9900 that is not colorful.
for m in range(9899, 0, -1):
    if not is_colorful(m):
        print(f"Largest non-colorful m: {m}")
        break
